  const PRIORITY = [["titan.work.emergency_service_coordinator","\\b(urgent|emergency|burst|no power|locked out|flood|active leak)\\b"],["titan.sales.quote_coordinator","\\b(quote|quotation|estimate price|send estimate|follow up quote)\\b"],["titan.sales.estimator","\\b(estimate|scope|price this|cost this|measure)\\b"],["titan.customer.booking_coordinator","\\b(book|booking|appointment|reschedule|cancel appointment)\\b"],["titan.work.dispatcher","\\b(dispatch|nearest|send (a |the )?(tech|technician|worker|cleaner|plumber|electrician)|day-of-work|delay)\\b"],["titan.work.scheduler","\\b(schedule|slot|availability|calendar|allocate time)\\b"],["titan.work.work_planner","\\b(plan (the )?job|job prep|materials needed|equipment needed|skills needed|work plan)\\b"],["titan.work.quality_coordinator","\\b(quality|qc|inspect|inspection|rework|defect)\\b"],["titan.work.job_completion_coordinator","\\b(completion|close (the )?job|completion photos|before and after|evidence)\\b"],["titan.money.billing_coordinator","\\b(invoice|bill customer|billing)\\b"],["titan.money.accounts_receivable_officer","\\b(overdue|unpaid|payment follow|collect payment|receivable)\\b"],["titan.assets.inventory_coordinator","\\b(stock|inventory|consumable|van stock|reorder)\\b"],["titan.procurement.materials_planner","\\b(materials|parts|supplies|supply shortage)\\b"],["titan.people.health_safety_coordinator","\\b(safety|hazard|incident|sds|chemical|ppe)\\b"],["titan.customer.service_recovery_coordinator","\\b(complaint|failed service|service recovery|unhappy|refund request)\\b"],["titan.marketing.reviews_referrals_coordinator","\\b(review|referral|testimonial)\\b"],["titan.marketing.reactivation_coordinator","\\b(dormant|reactivat|win back|old customer)\\b"],["titan.work.recurring_services_coordinator","\\b(recurring|repeat service|weekly|fortnightly|monthly service)\\b"],["titan.work.job_coordinator","\\b(job|work order|service request)\\b"],["titan.customer.receptionist","\\b(enquiry|inquiry|lead|new customer|phone call|incoming)\\b"]].map(([id,pattern])=>[id,new RegExp(pattern,'i')]);
